import type { Database } from "./db.ts";

export interface Task {
  id: number;
  title: string;
  created_at: string;
  updated_at: string;
  completed_at: string | null;
}

export interface TaskPage {
  tasks: Task[];
  total: number;
  limit: number;
  offset: number;
}

export const DEFAULT_LIMIT = 50;
export const MAX_LIMIT = 200;

/** Escapes `%`, `_` and the escape character itself so a search is always a plain substring match. */
function likePattern(search: string): string {
  return `%${search.replace(/[\\%_]/g, "\\$&")}%`;
}

/**
 * One page of tasks, open ones first (newest first), then completed ones (most recently completed first).
 * `search` keeps only the tasks whose title contains it, ignoring case; `total` counts all matches.
 */
export function listTasks(
  db: Database,
  { limit = DEFAULT_LIMIT, offset = 0, search = "" }: { limit?: number; offset?: number; search?: string } = {},
): TaskPage {
  const pattern = likePattern(search.trim());
  const [{ total }] = db.all(
    "SELECT COUNT(*) AS total FROM tasks WHERE title LIKE ? ESCAPE '\\'",
    pattern,
  ) as unknown as [{ total: number }];
  const tasks = db.all(
    `SELECT * FROM tasks WHERE title LIKE ? ESCAPE '\\'
     ORDER BY completed_at IS NOT NULL, COALESCE(completed_at, '') DESC, id DESC
     LIMIT ? OFFSET ?`,
    pattern,
    limit,
    offset,
  ) as unknown as Task[];
  return { tasks, total, limit, offset };
}

export function createTask(db: Database, title: string): Task {
  const now = new Date().toISOString();
  const [task] = db.all(
    "INSERT INTO tasks (title, created_at, updated_at) VALUES (?, ?, ?) RETURNING *",
    title.trim(),
    now,
    now,
  );
  return task as unknown as Task;
}
EOF
