cat > public/app.js <<'EOF'
const PAGE_SIZE = 20;
const SEARCH_DELAY_MS = 250;

const form = document.getElementById("task-form");
const titleInput = document.getElementById("task-title");
const searchInput = document.getElementById("task-search");
const list = document.getElementById("task-list");
const emptyState = document.getElementById("empty-state");
const pager = document.getElementById("pager");
const prevButton = document.getElementById("prev-page");
const nextButton = document.getElementById("next-page");
const pageStatus = document.getElementById("page-status");

let offset = 0;
let latestRequest = 0;
let searchTimer;

function emptyMessage(search) {
  return search
    ? `No tasks match "${search}". Try a different word.`
    : "Nothing to do yet 🎉 Add your first task above.";
}

async function showTasks() {
  const search = searchInput.value.trim();
  const request = ++latestRequest;
  const params = new URLSearchParams({ limit: PAGE_SIZE, offset });
  if (search) params.set("q", search);

  const response = await fetch(`/api/tasks?${params}`);
  const page = await response.json();
  if (request !== latestRequest) return; // a newer request superseded this one

  // Deleting or searching can leave the current page past the end: go back to the last one.
  if (page.tasks.length === 0 && page.total > 0) {
    offset = Math.floor((page.total - 1) / PAGE_SIZE) * PAGE_SIZE;
    return showTasks();
  }

  list.replaceChildren(
    ...page.tasks.map((task) => {
      const item = document.createElement("li");
      item.textContent = task.title;
      if (task.completed_at) item.style.textDecoration = "line-through";
      return item;
    }),
  );

  emptyState.hidden = page.total > 0;
  emptyState.textContent = page.total > 0 ? "" : emptyMessage(search);

  pager.hidden = page.total <= PAGE_SIZE;
  prevButton.disabled = offset === 0;
  nextButton.disabled = offset + PAGE_SIZE >= page.total;
  pageStatus.textContent = `${offset + 1}–${offset + page.tasks.length} of ${page.total}`;
}

form.addEventListener("submit", async (event) => {
  event.preventDefault();
  await fetch("/api/tasks", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ title: titleInput.value }),
  });
  titleInput.value = "";
  // Show the new task: it is the newest open one, so it sits at the top of the unfiltered list.
  searchInput.value = "";
  offset = 0;
  await showTasks();
});

searchInput.addEventListener("input", () => {
  clearTimeout(searchTimer);
  searchTimer = setTimeout(() => {
    offset = 0;
    showTasks();
  }, SEARCH_DELAY_MS);
});

prevButton.addEventListener("click", () => {
  offset = Math.max(0, offset - PAGE_SIZE);
  showTasks();
});

nextButton.addEventListener("click", () => {
  offset += PAGE_SIZE;
  showTasks();
});

showTasks();
EOF
